      SUBROUTINE ROTAT2(NM)CC     ROTATION OF SECOND-ORDER TRANSFER MATRIX ELEMENTCC ----------------------------------------------------------------------      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TS.CIN'      REAL            TSAV(6,6)CC     IDENTIFY MATRIX TO BE ROTATEDC      IF (NM .EQ. 0) THEN        DO 15 JKL = 1, 105   15   TSL(JKL) = TL(JKL)      ELSE        DO 55 JKL = 1, 105   55   TSL(JKL) = TVL(JKL)      ENDIFCC     ROTATE AT ENTRANCEC  100 DO 150 I = 1, 5      JK = 0      DO 120 K = 1, 6      DO 120 J = 1, K      JK = JK + 1      TSIJK = TS(I,JK)      IF (J .NE. K) TSIJK = 0.5*TSIJK      TSAV(J,K) = TSIJK  120 TSAV(K,J) = TSIJKC      DO 130 K = 1, 6      T1K = TSAV(1,K)      TSAV(1,K) = T1K*CSR - TSAV(3,K)*SNR      TSAV(3,K) = T1K*SNR + TSAV(3,K)*CSR      T2K = TSAV(2,K)      TSAV(2,K) = T2K*CSR - TSAV(4,K)*SNR      TSAV(4,K) = T2K*SNR + TSAV(4,K)*CSR  130 CONTINUEC      DO 140 J = 1, 6      TJ1 = TSAV(J,1)      TSAV(J,1) = TJ1*CSR - TSAV(J,3)*SNR      TSAV(J,3) = TJ1*SNR + TSAV(J,3)*CSR      TJ2 = TSAV(J,2)      TSAV(J,2) = TJ2*CSR - TSAV(J,4)*SNR      TSAV(J,4) = TJ2*SNR + TSAV(J,4)*CSR  140 CONTINUEC      JK = 0      DO 145 K = 1, 6      DO 145 J = 1, K      JK = JK + 1      TSIJK = TSAV(J,K)      IF (J .NE. K) TSIJK = 2.0*TSIJK  145 TS(I,JK) = TSIJK  150 CONTINUECC     ROTATE AT EXITC      JK = 0      DO 230 K = 1, 6      DO 230 J = 1, K      JK = JK + 1      TT(1,JK) = TS(1,JK)*CSR - TS(3,JK)*SNR      TT(3,JK) = TS(1,JK)*SNR + TS(3,JK)*CSR      TT(2,JK) = TS(2,JK)*CSR - TS(4,JK)*SNR      TT(4,JK) = TS(2,JK)*SNR + TS(4,JK)*CSR  230 CONTINUE      DO 240 I = 1, 4      DO 240 JK = 1, 21  240 TS(I,JK) = TT(I,JK)CC     REPLACE ROTATED MATRIXC  400 IF (NM .EQ. 0) THEN        DO 415 JKL = 1, 105  415   TL(JKL) = TSL(JKL)      ELSE        DO 465 JKL = 1, 105  465   TVL(JKL) = TSL(JKL)      ENDIFC  500 IF (NORD1 .GE. 3) CALL ROTAT3(NM)      RETURN      END